function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',4000)}
function modal(title,html){$('#modalContent').innerHTML=`<div class="modalhead"><h2>${title}</h2>${btn('✕','close')}</div>${html}`;if(!$('#modal').open)$('#modal').showModal()}
function kv(rows){return `<dl class="keyvals">${rows.map(([a,b])=>`<dt>${a}</dt><dd>${b}</dd>`).join('')}</dl>`}
function empty(t,desc='',action=''){return `<div class="empty"><span style="font-size:35px">◫</span><b>${t}</b><p>${desc}</p>${action}</div>`}
function select(label,key,opts,val){return `<label>${label}<select data-filter="${key}">${opts.map(([v,t])=>`<option value="${v}" ${String(val)===String(v)?'selected':''}>${t}</option>`).join('')}</select></label>`}
function field(label,key,type='text',extra=''){return `<label>${label}<input data-draft="${key}" type="${type}" value="${esc(state.draft[key])}" ${extra}></label>`}
function pagehead(title,sub,actions=''){return `<div class="pagehead"><div><div class="eyebrow">POWER ASSURANCE / UPS FLEET</div><h1>${title}</h1><p class="muted">${sub}</p></div><div class="actions">${actions}</div></div>`}
function globalNotice(){const map={offline:['浏览器离线 · 最后快照 '+stamp+'。确认和发布不可用，恢复后需重新核对未决操作。','error'],sourceDown:['告警同步异常 · 当前活动计数未知；上次同步计数已过期（09:59:00）。无法确认当前无告警。','error'],partial:['部分设备快照读取失败 · 成功数据仍可查看，统计不完整。失败设备保留在列表。',''],auditDown:['审计/请求意图存储不可用 · 新确认与发布已禁用，已有未知结果保留待核对。','error'],recovery:['配置切换未完成 · 已提交 cfg-8 / 最后成功 cfg-7。RECOVERY_REQUIRED，副作用闸门关闭。','error'],newCritical:[state.role==='viewer'?'新严重风险 · UPS-B01。冻结列表不跳行。<a href="#detail/ups-b01">立即查看 →</a>':'新严重风险 · UPS-A02 负载严重。冻结列表不跳行。<a href="#detail/ups-a02">立即查看 →</a>','error']};return map[state.scenario]?notice(...map[state.scenario]):''}
