function metric(label,v,unit='',note='源采集 · 10:00:00',quality='good',hist=true){return `<div class="metric"><button data-action="${hist&&typeof v==='number'?'metric:'+label:'metricInfo:'+label}"><label>${label} ${hist&&typeof v==='number'?'<span class="blue">↗</span>':''}</label><b class="${quality==='fault'?'red':''}">${v===null?'—':esc(v)}<small>${unit}</small></b><small>${note}</small></button></div>`}
function detail(){let d=current();if(state.scenario==='sourceDown')d={...d,coverage:'partial',risk:d.risk==='normal'?null:d.risk};const bad=d.runtime===null,local=alarms.filter(a=>a.eq===d.id&&a.activity==='active').slice(0,10);return pagehead(d.name,`${d.model} · ${d.location}`, '<a href="#overview">← 返回清单</a>'+btn('°'+(state.unit==='C'?'F':'C'),'unit')+'<a href="#history/'+d.id+'">历史趋势 ↗</a>')+`<div class="actions" style="margin-bottom:20px">${badge(d.comm)}${badge(d.mode)}${badge(d.risk||'unknown',d.risk?labels[d.risk]:'无法确认正常')}${badge(d.status)}<small>固定快照 · ${stamp} · 刷新不改变源时间</small></div><div class="hero"><div><label>设备续航估算</label><div class="big ${d.runtime!==null&&d.runtime<d.q?'red':''}">${d.runtime??'—'}<small>min</small></div><small>${bad?'当前不可评估 · 最后有效 14 min / 09:31:40（已过期）':'实测来源 · runtimeEstimateMinutes'}</small></div><div><label>业务持续供电要求</label><div class="big">${d.q}<small>min</small></div><small>工程配置 · cfg-${state.config} / R-01 v3</small></div><div><label>风险评估 · ${labels[d.coverage]}</label><h2 class="${d.risk==='critical'?'red':'green'}" style="font-size:25px;margin:10px 0">${d.risk?labels[d.risk]:'无法确认正常'}</h2><p class="muted">${d.id==='ups-a01'?'电池供电且续航 14 < 15 min，两个有效主采样触发。':d.id==='ups-a02'?'负载 110% ≥ 严重阈值 90%；确认不消除风险。':d.risk==='normal'?'必需观测通道与适用规则均有效，未发现已知活动风险。':'必要数据不可用，不能将数据不足显示为正常。'}</p>${btn('查看评估依据','assessment')}</div></div>
<div class="grid2"><section class="panel"><div class="panel-head"><h2>▥ 电池</h2>${select('电池串','string',[['串 A','串 A · bat-a'],['串 B','串 B · bat-b']],state.string)}</div><small>子对象 ${state.string==='串 A'?'bat-a':'bat-b'} · 父设备 ${d.id} · 示例磷酸铁锂 / 40 节</small><div class="metrics">${metric('串电压',bad?null:state.string==='串 A'?512:510,'V')}${metric('SOC',d.soc,'%','荷电状态 · 独立测量')}${metric('SOH',d.soh,'% ',d.soh===null?'不支持SOH · 型号能力依据':'健康状态 · 独立测量')}${metric('电池温度',temp(bad?null:28.4),'°'+state.unit)}${metric('电池电流',bad?null:16.5,'A','流出电池为正')}${metric('电池阻抗',bad?null:4.8,'mΩ','基准 4.0 mΩ · 同串/同测法')}</div></section>
<section class="panel"><div class="panel-head"><h2>◴ 负载与功率</h2>${badge('good','实测值')}</div><div class="metrics">${metric('有功功率',d.kw,'kW')}${metric('视在功率',d.kva,'kVA')}${metric('负载率',d.load,'%','按视在功率额定容量基准')}${metric('额定有功容量',d.site==='A'?108:72,'kW','铭牌配置 · cfg-7', 'good',false)}${metric('额定视在容量',d.site==='A'?120:80,'kVA','铭牌配置 · 非遥测','good',false)}${metric('负载评估',d.load===null?'不可评估':d.load>=90?'严重':d.load>=75?'警告':'正常','','W 75% / C 90%','good',false)}</div>${d.load>100?notice('110% 按原值完整显示；超载不等同量程错误。'):''}</section>
<section class="panel"><div class="panel-head"><h2>ϟ 电力电子</h2>${select('模块','module',[['整机','整机'],['模块 1','模块 1 · mod-1'],['模块 2','模块 2 · mod-2']],state.module)}</div><div class="metrics">${metric('输出电压',bad?null:230.2,'V','L1-N · 输出端 · '+state.module)}${metric('输出频率',bad?null:50,'Hz')}${metric('电压 THD',bad?null:2.1,'%','L1 · 电压总谐波失真')}${metric('整流器',bad?'未知':'正常','','设备状态','good',false)}${metric('风扇',bad?'未知':'正常','','设备反馈','good',false)}${metric('电容评估','不支持','','未提供电容健康能力','unsupported',false)}</div></section>
<section class="panel"><div class="panel-head"><h2>⌁ 环境</h2><small>关联传感器 · 配电室东墙</small></div><div class="metrics">${metric('环境温度',temp(26.1),'°'+state.unit)}${metric('相对湿度',state.scenario==='outOfRange'?132:46,'% ',state.scenario==='outOfRange'?'超量程，未参与评估 · observedValue':'传感器独立来源',state.scenario==='outOfRange'?'fault':'good')}${metric('空气质量','未映射','','传感器能力待核实','unmapped',false)}${metric('漏水','未知','','当前值 null · 不等于无漏水','unknown',false)}</div><p class="muted">环境传感器显式关联当前 UPS，保留原所属设备与位置。</p></section>
<section class="panel"><div class="panel-head"><h2>⇄ 旁路与切换</h2></div><div class="metrics">${metric('静态旁路可用',bad?'未知':'是','','设备反馈','good',false)}${metric('静态旁路激活',d.mode==='staticBypass'?'是':'否','','独立状态','good',false)}${metric('维修旁路可用','是','','设备能力','good',false)}${metric('维修旁路激活','否','','设备反馈','good',false)}${metric('切换状态','稳定','','当前状态','good',false)}${metric('切换时长','不支持','','无设备实测时长证据','unsupported',false)}</div></section>
<section class="panel"><div class="panel-head"><h2>▣ 维护建议</h2>${badge('warning','计划提醒')}</div><h3>电池定期检测</h3><p class="muted">到期 2026-09-20 · 提前 30 天 · 厂家计划 / rev2</p><details><summary>查看规则、输入时间及缺失项</summary><p>R-04 按站点日期评估，与遥测无关；计划提醒无需告警确认。</p><p>R-03 阻抗变化 20%，当前无批准阈值，规则未启用，仅展示变化。</p><small>最后成功评估 ${stamp}；缺失：批准阻抗阈值。无寿命预测。</small></details>${canEdit()?'<a href="#config">更新计划与完成证据 →</a>':''}</section></div><section class="panel"><div class="panel-head"><h2>本机活动告警</h2>${btn('查看全部事件 →','deviceEvents')}</div>${alarmTable(local)}</section>`}
function assessment(){let d=current();if(state.scenario==='sourceDown')d={...d,coverage:'partial',risk:d.risk==='normal'?null:d.risk};modal('风险与覆盖 · '+d.name,notice('风险等级与数据覆盖独立；已知严重风险不会因质量差而消失。')+kv([['风险',badge(d.risk||'unknown',d.risk?labels[d.risk]:'无法确认正常')],['数据覆盖',labels[d.coverage]],['有效观测',d.coverage==='complete'?'B 基础健康、A 告警同步、R-05、R-01、R-02、R-04':'R-05 质量异常评估有效；B 基础数据不可用'],['未启用规则','R-03 阻抗 · 无批准阈值'],['最后成功评估',stamp],['规则输入','续航 09:59:39 / 09:59:40 两个主采样；模式 09:59:40；Q 为静态配置'],['恢复条件','R ≥ Q+2 min，连续 2 次有效主样本，时间门槛 0ms；数据无效清候选但不恢复活动告警'],['版本','cfg-7 · R-01 v3 · epoch-7']]));}
function chart(unit,index=0){const end=state.historyRange==='custom'&&state.historyTo?new Date(state.historyTo):new Date('2026-09-14T10:00:00');const start=state.historyRange==='custom'&&state.historyFrom?new Date(state.historyFrom):new Date(end-Number(state.historyRange==='custom'?1:state.historyRange)*3600000);const tick=f=>{const d=new Date(+start+(end-start)*f);return (end-start>86400000?(d.getMonth()+1)+'/'+d.getDate()+' ':'')+String(d.getHours()).padStart(2,'0')+':'+String(d.getMinutes()).padStart(2,'0')};const ys=[118,113,124,105,98,109,80,91,63,71,80,58,93,89,74,79,84];let pts=ys.map((v,i)=>`${55+i*43},${v+index*4}`);return `<svg class="chart" viewBox="0 0 800 220" role="img" aria-label="${unit} 历史趋势，包含数据缺口、尖峰范围及映射版本边界"><g>${[40,80,120,160].map((y,i)=>`<line class="grid" x1="50" y1="${y}" x2="785" y2="${y}"/><text x="5" y="${y+4}">${120-i*30}</text>`).join('')}</g><rect x="314" y="25" width="86" height="143" fill="#28303d"/><text x="318" y="190">采集缺口</text><path d="M55,95 L98,90 L141,101 L184,82 L227,75 L270,86 L270,132 L227,121 L184,128 L141,147 L98,136 L55,141 Z" fill="#4dd4ad" opacity=".11"/><polyline points="${pts.slice(0,6).join(' ')}" fill="none" stroke="#4dd4ad" stroke-width="2.5"/><polyline points="${pts.slice(9).join(' ')}" fill="none" stroke="#4dd4ad" stroke-width="2.5"/><line x1="571" y1="22" x2="571" y2="115" stroke="#4dd4ad"/><line x1="443" y1="20" x2="443" y2="165" stroke="#8dacdd" stroke-dasharray="4 4"/><text x="451" y="25">cfg-6 → cfg-7</text><text x="50" y="212">${tick(0)}</text><text x="220" y="212">${tick(.25)}</text><text x="410" y="212">${tick(.5)}</text><text x="600" y="212">${tick(.75)}</text><text x="730" y="212">${tick(1)}</text></svg>`}
function history(){const d=current();return pagehead('历史趋势',d.name+' · Asia/Singapore (UTC+08:00) · 按当时有效映射解释','<a href="#detail/'+d.id+'">← 返回设备</a>')+`<div class="panel"><div class="filters">${select('时间范围','historyRange',[['1','最近1小时'],['24','最近24小时'],['168','最近7天'],['custom','自定义（≤7天）']],state.historyRange)}<label>起始时间<input id="from" type="datetime-local" value="2026-09-14T09:00"></label><label>结束时间<input id="to" type="datetime-local" value="2026-09-14T10:00"></label>${select('样例读取状态','historyStatus',[['normal','正常 / 缺口 / 映射边界'],['empty','无历史'],['single','单样本'],['partial','局部读取失败'],['error','历史服务失败'],['forbidden','历史权限不足']],state.historyStatus)}${btn('查询趋势','queryHistory','primary')}</div><div class="actions">${['负载率','SOH','SOC','电池温度','输出电压','串电压'].map(x=>`<label class="checkline"><input type="checkbox" data-series="${x}" ${state.historyFields.includes(x)?'checked':''}>${x}</label>`).join('')}</div><p class="muted">最多4条；不同单位分图；每曲线最多1000点。缺口不插值，min/max 范围保留尖峰。</p></div>${['empty','error','forbidden'].includes(state.historyStatus)?`<div class="panel">${empty({empty:'该字段没有历史数据',error:'历史服务不可用',forbidden:'无历史读取权限'}[state.historyStatus],'实时页面不受此历史读取状态影响。',btn('重试','retryHistory'))}</div>`:state.historyFields.map((f,i)=>`<div class="panel"><div class="panel-head"><h2>${f} <small> / ${f.includes('温度')?'°'+state.unit:f.includes('电压')?'V':'%'}</small></h2>${badge(state.historyStatus==='partial'?'warning':'good',state.historyStatus==='single'?'仅 1 个有效样本':'覆盖 83.3% · 固定周期')}</div>${state.historyStatus==='partial'?notice('旧源 cfg-6 读取失败，该区间保持空缺；当前 cfg-7 可读。'):''}${state.historyStatus==='single'?'<div class="empty">● 09:30:00 · 76%<p>单样本，无连接线</p></div>':chart(f,i)}<div class="legend"><span class="green">━ 平均值</span><span>▥ min/max 范围带</span><span>▧ 缺失区间</span><span>┆ 映射边界</span></div><details><summary>映射版本与聚合说明</summary>${kv([['聚合粒度','1分钟 / 固定演示数据；范围选择改变查询说明'],['查询窗口',esc(state.historyLabel||'2026-09-14 09:00 至 10:00（1小时）')],['cfg-6 区间','[09:00,09:30) · 旧源 P1 / scale 1'],['cfg-7 区间','[09:30,10:00) · 新源 P2 / scale 2'],['边界语义','09:30 样本只属于新段；分桶不跨版本。旧源缺失不以新点补齐。'],['资产代次','assetGeneration-1 · 更换整机会断开曲线']])}</details></div>`).join('')}`}
function visibleAlarms(){return alarms.filter(a=>accessible().some(d=>d.id===a.eq))}
function alarmTable(as){return as.length?`<div class="tablewrap"><table><thead><tr>${['严重度 / 类型','告警 / 事件','设备','发生时间','活动状态','确认状态',''].map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${as.map(a=>`<tr><td>${badge(a.level)}<br><small>${a.kind==='event'?'计划事件':'告警'}</small></td><td><strong>${esc(a.title)}</strong><small>${a.source}${a.sync==='OUTCOME_UNKNOWN'?' · 已检测风险，待同步':''}</small></td><td>${devices.find(d=>d.id===a.eq)?.name}</td><td>2026-09-14 ${a.time}${a.received>a.time&&a.id==='occ-105'?'<br><span class="amber">迟到事件 · 接收 '+a.received+'</span>':''}</td><td>${badge(a.activity)}</td><td>${badge(a.ack,a.pending?'状态待核对':undefined)}</td><td>${btn('详情','alarm:'+a.id,'link')}${a.kind==='alarm'&&a.ack==='unacknowledged'&&!a.pending?btn('确认','ack:'+a.id,'',!canAck()):''}${a.pending?btn('核对状态','operation:'+a.id,'link'):''}</td></tr>`).join('')}</tbody></table></div>`:empty('没有符合条件的事件','可切换“全部事件”查看恢复与计划记录。')}
function alarmPage(){let as=visibleAlarms().filter(a=>(state.alarmView==='all'||a.activity==='active')&&(!state.alarmEq||a.eq===state.alarmEq)&&(!state.alarmAck||a.ack===state.alarmAck)&&(!state.alarmActivity||a.activity===state.alarmActivity)&&(!state.alarmLevel||a.level===state.alarmLevel)&&(!state.site||devices.find(d=>d.id===a.eq).site===state.site)&&(!state.alarmFrom||'2026-09-14T'+a.time>=state.alarmFrom)&&(!state.alarmTo||'2026-09-14T'+a.time<=state.alarmTo)).sort((a,b)=>(state.alarmView==='active'?({critical:0,warning:1,info:2}[a.level]-{critical:0,warning:1,info:2}[b.level]):0)||b.time.localeCompare(a.time)||a.id.localeCompare(b.id));return pagehead('告警与事件','活动状态、确认状态与来源质量独立呈现。',btn('↻ 刷新列表','refresh'))+`<div class="tabs">${btn('活动告警','alarmView:active',state.alarmView==='active'?'active':'')}${btn('全部事件','alarmView:all',state.alarmView==='all'?'active':'')}</div><div class="panel"><div class="filters">${select('站点','site',[['','全部授权站点'],...[...new Set(accessible().map(d=>d.site))].map(x=>[x,x+'站点'])],state.site)}${select('设备','alarmEq',[['','全部设备'],...accessible().map(d=>[d.id,d.name])],state.alarmEq)}${select('严重度','alarmLevel',[['','全部'],...['critical','warning','info'].map(x=>[x,labels[x]])],state.alarmLevel)}${select('活动状态','alarmActivity',[['','全部'],...['active','cleared','administrativelyClosed','unknown','notApplicable'].map(x=>[x,labels[x]])],state.alarmActivity)}${select('确认状态','alarmAck',[['','全部'],...['unacknowledged','acknowledged','notRequired'].map(x=>[x,labels[x]])],state.alarmAck)}<label>发生时间起<input type="datetime-local" data-filter="alarmFrom" value="${state.alarmFrom}"></label><label>发生时间止<input type="datetime-local" data-filter="alarmTo" value="${state.alarmTo}"></label></div>${alarmTable(as)}<div class="pagination"><span>冻结成员 ${as.length} 条 · list-${state.listRevision} · 当前统计 ${state.scenario==='sourceDown'?'未知':'截至10:00:00'}</span><span>每页50条 · 第1页 ${btn('上一页','noop','',true)} ${btn('下一页','noop','',true)}</span></div></div>`}
function alarmDetail(id){const a=visibleAlarms().find(x=>x.id===id);if(!a)return;modal('事件详情 · '+id,`${badge(a.level)} ${badge(a.activity)} ${badge(a.ack)}<h2 style="margin:16px 0">${esc(a.title)}</h2>${kv([['设备',devices.find(d=>d.id===a.eq).name],['来源',a.source],['来源质量',state.scenario==='sourceDown'?'未知 · 最后同步09:59:00':'good · 10:00:00'],['平台同步',a.sync||'APPLIED'],['接收时间','2026-09-14 '+a.received],['备注',esc(a.comment)||'—'],['事件阶段',a.stage||'非计划事件']])}<div class="timeline"><div><b>发生</b><p class="muted">2026-09-14 ${a.time}</p></div>${a.ack==='acknowledged'?`<div><b>确认 · ${esc(a.actor)}</b><p class="muted">${a.ackTime} · ${esc(a.comment)}</p></div>`:''}${a.clear?`<div><b>自然恢复</b><p class="muted">${a.clear} · 独立于确认</p></div>`:''}${state.scenario==='sourceDown'?'<div>来源未知 · 保留最后活动状态</div>':'<div><b>再同步</b><p class="muted">10:00:00 · 源状态回读</p></div>'}</div>${a.kind==='event'?notice('纯计划事件，无需确认；计划完成通过工程配置提交证据。'):a.ack==='unacknowledged'?btn('确认此告警','ack:'+id,'primary',!canAck()):notice('告警已确认；仍活动的严重告警保持严重样式。')}`)}
function ackDialog(id){const a=visibleAlarms().find(x=>x.id===id);if(!a||!canAck())return;if(state.scenario==='unsupportedAck'){modal('平台不支持此确认',notice('目标平台不支持恢复后确认。VG-05 阻断；不能用前端已读替代 FIN 确认。','error'));return}modal('确认告警',notice('静态交互演示：不会向 FIN 发送请求。确认仅表示知悉，不改变活动/恢复状态。')+kv([['设备',devices.find(d=>d.id===a.eq).name],['描述',esc(a.title)],['发生时间','2026-09-14 '+a.time],['当前状态',badge(a.activity)+' '+badge(a.ack)],['确认人','示例当前会话 · 陈工']])+`<label>确认备注（必填，1–500字符）<textarea id="ackComment" maxlength="500" placeholder="请输入处理说明"></textarea></label><p id="ackError" class="red" role="alert"></p><div class="actions">${btn('取消','close')}${btn('提交确认','submitAck:'+id,'primary')}</div>`)}
const steps=['注册设备','声明能力','点位映射','历史 / 规则','校验','发布'];
function config(){const d=state.draft;return pagehead('工程配置','以设备专属草稿配置接入，校验后发布新版本。',btn('版本历史 / 回退','versions')+btn('保存草稿','saveDraft'))+`<div class="steps">${steps.map((x,i)=>btn(`<em>${i+1}</em>${x}`,'step:'+i,state.step===i?'active':'')).join('')}</div><div class="split"><div class="panel"><div class="panel-head"><h2>${state.step+1}. ${steps[state.step]}</h2><span class="version">draft-local · base cfg-${state.config}</span></div>${configStep()}<div class="actions" style="margin-top:25px">${btn('上一步','step:'+Math.max(0,state.step-1),'',state.step===0)}${state.step<5?btn('下一步','step:'+(state.step+1),'primary'):''}</div></div><div><div class="panel"><h2>草稿摘要</h2>${kv([['注册设备',esc(d.name)],['状态',badge('draft')],['支持状态',esc(d.support)],['映射字段',esc(d.logical)],['基线版本','cfg-'+state.config],['校验',state.validated?badge('good','已校验 / 10分钟有效'):badge('warning','待校验')],['变更方式','仅提交有权对象的局部 patch'],['证据版本',esc(d.evidence)]])}</div><div class="panel"><h3>接入步骤说明</h3><p class="muted">发布后进入“待验收”。必要采集、告警通道及历史证据通过接入验收后，才参与生产监控。</p><p class="muted">关键映射变更会撤销旧验收；活动规则或未决操作阻断破坏恢复链路的变更。</p></div></div></div>`}
function configStep(){const d=state.draft;switch(state.step){case 0:return `<div class="formgrid">${select('可访问 FIN 设备（未重复注册）','draftEq',[['ups-a03','UPS-A03 · 待接入'],['fixture-new','UPS-A04 · 未登记样例']],d.eq)}${field('显示名称','name','text','maxlength="100"')}${field('点表 / 证据文件版本','evidence')}${select('接入状态变更','draftEnrollment',[['ready','待验收 / 重新启用'],['disabled','停用'],['retired','退役']],d.enrollment)}</div>${kv([['站点 / 设备 Ref','site-a / '+esc(d.eq)],['设备状态','ready → accepted（验收后）'],['源记录位置','A站点 · 扩建机房'],['连接器','只读引用 · 主连接 fixture-conn-a'],['型号 / 固件','示例 UPS 型号 / fw-example-1']])}${notice('插件登记只引用 FIN 资产；设备地址和密码由平台工程流程管理。')}`;
case 1:return `<details><summary>可选整体评分 / 维护展望绑定</summary><div class="formgrid">${field('整体评分来源 Ref（可空）','healthSource')}${field('评分方法 / 版本依据','healthMethod')}${field('外部展望来源 Ref（可空）','outlookSource')}</div><p class="muted">仅引用既有可读对象。无绑定不阻断基础监控；评分需0–100、有效质量及方法证据，不从SOC/SOH折算。</p></details><div class="formgrid">${select('能力声明','draftSupport',[['supported','支持'],['unsupported','不支持'],['unverified','未验证']],d.support)}${field('能力依据（不支持必填）','reason')}</div><div class="tablewrap"><table><thead><tr><th>能力集合</th><th>包含项</th><th>用途</th></tr></thead><tbody><tr><td>B 基础运行</td><td>主连接、供电模式、负载、续航</td><td>接入验收 / R-05</td></tr><tr><td>A 告警通道</td><td>源身份、同步、确认、恢复</td><td>必须验证</td></tr><tr><td>I 规则输入</td><td>R-01 续航、模式、Q</td><td>按规则声明</td></tr><tr><td>O 可选展示</td><td>SOC/SOH、环境、风扇</td><td>可缺失，保留说明</td></tr></tbody></table></div>${notice('未验证不等于已验收；可选字段缺失不扩大 B 集合。环境点可来自同站点显式关联传感器。')}`;
case 2:return `<div class="formgrid">${field('logicalField','logical')}${field('源点名称 / Ref','point')}${field('原始单位','rawUnit')}${field('归一单位','unit')}${field('scale','scale','number','step="any"')}${field('offset','offset','number','step="any"')}${field('电流正负约定','sign')}${field('证据版本','evidence')}${field('rawKind','rawKind')}${field('normalizedKind','normalizedKind')}${field('origin（measured/configured/derived）','origin')}${field('显示精度','precision','number','min="0" max="6"')}${field('枚举映射','enumMap')}${field('相别','phase')}${field('测量位置','measurementLocation')}${field('目标对象 / 电池串 / 模块','targetObject')}${field('传感器关联依据','association')}${field('预期采样周期（秒）','expectedInterval','number','min="1"')}</div><label class="checkline"><input type="checkbox" data-draft="reuse" ${d.reuse?'checked':''}>声明合理源复用（须提供依据）</label>${kv([['对象归属','targetObjectRef='+esc(d.eq)+' · 整机'],['类型 / 精度','rawKind=Number → normalizedKind=Number / 1位小数'],['转换公式','normalized = raw × scale + offset'],['相别 / 测量位置','负载为整机；电压映射示例 L1 / 输出端'],['枚举映射','powerMode: 1→utility, 2→battery；未知码→unknown'],['质量 / 历史策略','30秒过期下限 · 不因读取缓存刷新时间'],['源复用','默认不复用；冲突含义禁止复用']])}${btn('只读点预览','pointPreview')}${notice('此处只预览固定样例，不会以演示值证明现场校验通过。')}`;
case 3:return `<h3>历史工程预检</h3><div class="formgrid">${field('期望留存天数','retention','number','min="1"')}</div><label class="checkline"><input type="checkbox" data-draft="history" ${d.history?'checked':''}>必要历史归档 / 365天留存已回读核验（演示声明）</label><p class="muted">发布不修改平台历史；实际归档由工程流程设置后回读。</p><div class="rulebox"><h3>R-01 续航</h3><label class="checkline"><input type="checkbox" data-draft="r01" ${d.r01?'checked':''}>启用（本型号验收必需）</label><div class="formgrid">${field('业务要求 Q (min)','q','number','min="0.1" step="0.1"')}${field('有效样本次数 N','n','number','min="1"')}${field('持续时间 (ms)','duration','number','min="0"')}</div><small>R &lt; Q 触发；R ≥ Q+2 恢复；次数与时间 AND；仅主输入新证据推进。</small></div><div class="rulebox"><h3>R-02 负载</h3><label class="checkline"><input type="checkbox" data-draft="r02" ${d.r02?'checked':''}>启用</label><div class="formgrid">${field('警告阈值 W (%)','w','number')}${field('严重阈值 C (%)','c','number')}${field('警告回差 Hw','hw','number')}${field('严重回差 Hc','hc','number')}${field('触发样本次数','triggerN','number')}${field('升级样本次数','upgradeN','number')}${field('降级样本次数','downgradeN','number')}${field('恢复样本次数','clearN','number')}${field('最大输入时间差（秒）','maxInputSkew','number')}${field('最大采样间隔（秒）','maxSampleGap','number')}</div><small>各转换采用 N=${d.n}，duration=${d.duration}ms；升降级保持同一发生身份。</small></div><div class="rulebox"><h3>R-03 阻抗</h3><label class="checkline"><input type="checkbox" data-draft="r03" ${d.r03?'checked':''}>有工程批准依据，启用阻抗规则</label><div class="formgrid">${field('同对象 / 测法基准（mΩ）','impedanceBase','number')}${field('变化阈值 W (%)','impedanceW','number')}${field('回差 H (%)','impedanceH','number')}</div><p class="muted">d=(I-B)/B×100；d≥W触发，d&lt;W-H恢复；未启用时仅展示。</p><h3>R-05 必要数据质量</h3><p class="muted">已验收设备必需；bad持续5秒触发，全部B获得新证据且good连续5秒才恢复。</p></div><div class="rulebox"><h3>R-04 维护计划</h3><div class="formgrid">${field('计划标题','planTitle')}${field('到期日（站点日期）','due','date')}${field('提前提醒天数','remind','number','min="0" max="365"')}${select('计划状态','draftPlanStatus',[['scheduled','已计划'],['completed','已完成'],['cancelled','已取消']],d.planStatus)}${field('完成日期','completed','date')}${field('完成 / 变更证据','planEvidence')}</div><small>修改产生新修订，旧提醒标替代；完成 / 取消均为纯事件，不产生物理恢复。</small></div>`;
case 4:return `${btn('运行离线表单校验','validate','primary')}<p class="muted">检查字段与规则约束；现场引用、权限、单位元数据需 FIN 校验，此原型不予认证。</p>${state.validationHtml||notice('尚未生成校验报告。报告含阻断、警告、信息和整改位置。')}`;
case 5:return `${notice('发布将演示准备、提交、统一激活和审计流程。只改变当前浏览器的原型状态。')}${kv([['授权变更范围',esc(d.eq)+' / '+esc(d.logical)],['变更影响','配置草稿、能力、映射、设备专属规则与维护计划'],['基础版本','cfg-'+state.config],['校验报告',state.validated?'validation-local · 有效期10分钟':'未通过校验'],['发布状态',badge(state.pub==='ACTIVE'?'good':'warning',state.pub)]])}<label>发布理由<textarea id="publishReason" maxlength="500" placeholder="说明此次配置变更"></textarea></label><div class="actions" style="margin-top:15px">${btn('预览并发布','publishPreview','primary',!state.validated||!canEdit()||['offline','auditDown','recovery'].includes(state.scenario))}</div><p class="muted">发布后状态为 ready；不直接设为 accepted。</p>`;
}}
function validation(){const d=state.draft,errors=[];if(d.healthSource&&!d.healthMethod.trim())errors.push(['整体评分绑定','来源存在但方法依据缺失','填写方法/版本证据']);if(!d.name.trim())errors.push(['注册设备 / 名称','不能为空','填写显示名称']);if(!d.evidence.trim())errors.push(['证据版本','必填','引用点表版本']);if(d.support==='unsupported'&&!d.reason.trim())errors.push(['能力 / 依据','不支持必须有依据','填写来源文件与结论']);if(d.support==='unverified')errors.push(['必要能力','尚未验证','完成基础能力验证']);if(d.support==='unsupported')errors.push(['B / 必要负载','必需能力不支持','选用满足基础集合的能力档案']);if(!d.point.trim())errors.push(['映射 / 源点','源引用为空','选择有权源点']);if(d.unit!==d.rawUnit)errors.push(['映射 / 单位','此演示未注册该换算','使用同量纲已注册转换']);if(!['Number','Bool','Str'].includes(d.rawKind)||!['Number','Bool','Str'].includes(d.normalizedKind)||!['measured','configured','derived'].includes(d.origin))errors.push(['映射 / 类型来源','非法类型或来源枚举','使用已声明的类型']);if(d.rawKind!==d.normalizedKind)errors.push(['映射 / 类型','未注册该类型转换','保持类型一致或声明转换']);if(!d.r01)errors.push(['验收 / R-01','本型号验收必需规则未启用','发布启用或修改受评审能力档案']);if(d.r03&&!(Number(d.impedanceBase)>0&&Number(d.impedanceW)>0&&Number(d.impedanceH)>0&&Number(d.impedanceH)<Number(d.impedanceW)))errors.push(['R-03 / 参数','基准、阈值及回差非法','修正批准参数']);if(d.enrollment==='retired'&&!d.planEvidence.trim())errors.push(['退役 / 管理结束证据','缺少可回读源证据','提供管理结束记录，不能填写物理恢复']);if(!d.sign.trim())errors.push(['映射 / 正负约定','约定缺失','填写电流方向']);if(![d.scale,d.offset].every(x=>Number.isFinite(Number(x))))errors.push(['转换','必须为有限数','修正比例/偏移']);if(!(Number(d.q)>0))errors.push(['R-01 / Q','需求必须大于0','填写有效分钟数']);if(!(Number(d.w)<Number(d.c)&&Number(d.hw)>0&&Number(d.hw)<Number(d.w)&&Number(d.hc)>0&&Number(d.hc)<Number(d.c)-Number(d.w)))errors.push(['R-02 / 阈值回差','不满足 W<C、0<Hw<W、0<Hc<C-W','修正阈值和回差']);if(!(Number.isInteger(Number(d.n))&&Number(d.n)>=1&&Number.isInteger(Number(d.duration))&&Number(d.duration)>=0))errors.push(['规则 / 门槛','次数≥1、时长≥0且为整数','修正样本门槛']);if(!d.history)errors.push(['历史 / 必需策略','必要历史未核验','完成工程预检或能力豁免']);if(!d.due||Number(d.remind)<0||Number(d.remind)>365||!Number.isInteger(Number(d.remind)))errors.push(['计划 / 日期','日期及提醒范围非法','填写日期与0–365整数']);if(d.planStatus==='completed'&&(!d.completed||!d.planEvidence.trim()))errors.push(['计划 / 完成','完成日期与证据必填','提供完成凭据']);if(state.scenario==='activeBlock')errors.push(['活动规则 / occ-101','ACTIVE_OCCURRENCE_BLOCKS_CHANGE','保留旧规则自然恢复，或取得平台管理结束证据；确认不能解除']);state.validated=!errors.length;state.validatedAt=Date.now();state.validationHtml=`${notice(errors.length?`${errors.length} 个阻断 · 不可发布`:'离线表单约束通过 · 不代表 FIN 工程验收',errors.length?'error':'ok')}<div class="tablewrap"><table><thead><tr><th>级别</th><th>位置</th><th>原因</th><th>整改动作</th></tr></thead><tbody>${errors.map(e=>`<tr><td>${badge('critical','阻断')}</td>${e.map(x=>`<td>${esc(x)}</td>`).join('')}</tr>`).join('')}<tr><td>${badge('warning')}</td><td>O / 空气质量</td><td>可选字段未映射</td><td>可保留并记录原因</td></tr><tr><td>${badge('info')}</td><td>平台绑定</td><td>FIN 精确版本未核验</td><td>完成 VG-01～08</td></tr></tbody></table></div>`;state.step=4;render()}
function commission(){const d=devices.find(x=>x.id===state.draft.eq)||devices[4];return pagehead('接入验收','发布配置与工程验收分开；证据必须匹配当前版本。')+`<div class="panel"><div class="panel-head"><h2>${esc(d.name)} · 验收报告</h2>${badge(d.status)}</div>${kv([['配置指纹','cfg-'+state.config+' / mapping-'+state.config+' / capability-'+state.config+' / rules-'+state.config],['型号 / 固件','示例型号 / fw-example-1'],['点表版本',esc(state.draft.evidence)],['验收人','当前会话 · 陈工（示例）']])}${['B逐点单位、枚举、时间与源面板对照','A告警发生、确认、恢复生命周期测试','断线及恢复证据记录','历史归档、缺口和保留策略结果','可选缺失项与明确豁免'].map((t,i)=>`<label class="checkline"><input type="checkbox" class="acceptCheck" value="${i}">${t}</label>`).join('')}<div class="formgrid"><label>证据引用<input id="acceptEvidence" placeholder="验收报告路径 / 编号"></label><label>报告配置版本<input id="acceptRevision" value="cfg-${state.config}"></label></div><p id="acceptError" class="red" role="alert"></p>${btn('提交验收（演示）','accept','primary',d.status!=='ready'||['offline','auditDown','recovery'].includes(state.scenario))}<p class="muted">验收通过才进入 accepted / enabled=true。重新启用设备先返回 ready。</p></div>`}
function diagnostics(){const recovering=state.scenario==='recovery';return pagehead('运行诊断','只读检查版本一致性、数据质量及待核对操作。',btn('刷新诊断','refresh'))+`<div class="cards">${[['生命周期',recovering?'DEGRADED':'RUNNING'],['已提交版本',recovering?'cfg-8':'cfg-'+state.config],['最后成功版本','cfg-'+state.config],['待核对操作',state.operations.filter(o=>o.state==='OUTCOME_UNKNOWN').length],['规则待发命令',state.scenario==='sourceDown'?1:0],['告警同步',state.scenario==='sourceDown'?'未知':'good']].map(([a,b])=>`<div class="stat"><label>${a}</label><b style="font-size:20px">${b}</b></div>`).join('')}</div><div class="grid2"><div class="panel"><h2>连接与质量统计</h2>${kv([['主连接 A','online · 10:00:00'],['主连接 B','degraded · 09:31:40'],['点质量','good 42 · stale 4 · unsupported 6 · unmapped 2'],['历史错误','0 / 最近1小时'],['规则错误','0；R-03 未启用有明确依据'],['副作用闸门',recovering?'关闭 · 禁止混版运行':'打开 · epoch-'+state.config],['请求ID','sample-diag-024']])}</div><div class="panel"><h2>配置激活</h2>${kv([['Publication',recovering?'RECOVERY_REQUIRED':state.pub],['模块一致性',recovering?'规则模块未完成 cfg-8 激活':'所有模块 cfg-'+state.config],['恢复路径',recovering?'仅尝试已提交 cfg-8；显式恢复发布创建新版本':'按持久提交决定重建'],['FIN版本','unknown · 兼容性 unverified'],['敏感信息','不显示凭据或完整内部堆栈']])}${recovering?btn('建立恢复发布草稿','rollback:7'):''}</div></div><div class="panel"><h2>操作待核对</h2>${state.operations.length?state.operations.map(o=>`<div class="rulebox">${kv([['操作ID',o.id],['状态',o.state],['结果可用性',o.availability],['动作 / 目标',o.action+' / '+o.target]])}${o.state==='OUTCOME_UNKNOWN'||o.availability==='pending'?btn('只读核对状态','operation:'+o.target):''}</div>`).join(''):empty('没有未决操作','未知结果不会自动重发变更。')}</div>`}
function audit(){return pagehead('操作审计','仅追加、只读展示；确认、发布、回退及拒绝均保留结果。')+`<div class="panel"><div class="filters"><label>起始日期<input id="auditFrom" type="date" value="2026-09-08"></label><label>结束日期<input id="auditTo" type="date" value="2026-09-14"></label><label>动作<select id="auditAction"><option value="">全部动作</option><option>告警确认</option><option>配置发布</option><option>接入验收</option><option>回退草稿</option></select></label>${btn('查询','queryAudit')}</div><p id="auditError" class="red"></p><div id="auditRows">${auditRows()}</div></div>`}
function auditRows(action='',from='2026-09-08',to='2026-09-14'){const rows=state.audit.filter(x=>(!action||x.action===action)&&x.time.slice(0,10)>=from&&x.time.slice(0,10)<=to);return `<div class="tablewrap"><table><thead><tr>${['时间 / 人员','动作','目标 / 操作ID','结果','版本变化 / 脱敏差异'].map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.map(x=>`<tr><td>${x.time}<br><small>陈工 · sample-actor</small></td><td>${x.action}</td><td>${esc(x.target)}<br><small>${x.id}</small></td><td>${badge(x.outcome==='SUCCEEDED'?'good':'warning',x.outcome)}</td><td>${esc(x.diff)}</td></tr>`).join('')}${(!action||action==='外部确认回读')&&from<='2026-09-14'&&to>='2026-09-14'?`<tr><td>2026-09-14 09:43:06<br><small>李工 · 源系统确认</small></td><td>外部确认回读</td><td>occ-103<br><small>source-result-103</small></td><td>${badge('good','已确认')}</td><td>关联平台审计；不声称覆盖全部外部操作</td></tr>`:''}</tbody></table></div><p class="muted">默认7天，单次最多31天。操作记录不可编辑或删除。</p>`}
function log(action,target,outcome,diff=''){const id='sample-op-'+(state.audit.length+1);state.audit.unshift({id,action,target,outcome,diff,time:'2026-09-14 10:00:'+String(state.audit.length+1).padStart(2,'0')});return id}
const coverageItems=[['SF-01～03','总览 / 详情 / 评审场景','质量、来源时间、通讯、模式；固定数据不伪装现场刷新'],['SF-04','设备总览','过滤、统计、分页、返回上下文与新严重提示'],['SF-05','UPS详情','电池串、负载、电子、环境、旁路、维护与本机告警'],['SF-06 / 5.6','历史趋势','≤4曲线、≤7天、单位分图、缺口、版本边界与异常状态'],['SF-07 / 11 / 12','告警与事件','单条确认、备注、生命周期、未知结果及结果投影待同步'],['SF-08 / 14 / 15 / 16','工程配置','六步、草稿、校验、发布、冲突、回退、活动发生阻断'],['SF-09 / 10','规则参数 / 风险依据','R-01～05、主样本门槛、回差、风险与覆盖独立'],['SF-13','操作审计','只读追加记录，日期窗口及结果'],['OP-01 / FR-14','右上角身份','工程师全站点、操作员A、查看者B、无查看权限'],['OP-07 / 12','运行诊断','已提交 / 最后成功版本、闸门、待核对操作'],['OP-14 / 3.5','接入验收','证据、版本指纹、ready → accepted'],['FT-01～36 / VG-01～08','测试边界','静态页面无法证明后台事务、幂等、真实历史、平台权限、性能与现场兼容']];
function coverage(){return pagehead('规格对照','按 FSD v0.1 修订3追踪界面入口与静态实现边界。')+notice('原型完整性与生产验收分开：以下交互使用固定夹具；后台事务、源身份和真实时延需要后续 FIN 实现验证。')+`<div class="panel"><div class="tablewrap"><table><thead><tr><th>规格</th><th>页面入口</th><th>覆盖内容 / 边界</th></tr></thead><tbody>${coverageItems.map(r=>'<tr>'+r.map(x=>'<td style="white-space:normal">'+x+'</td>').join('')+'</tr>').join('')}</tbody></table></div></div><div class="panel"><h2>可检视异常场景</h2><p>通过顶部“评审场景”切换离线、部分失败、会话失效、数据异常、发布冲突、待核对等状态。</p><p class="muted">FSD未给出逐像素线框图；本原型沿用既有深色工业仪表盘视觉，按功能条款对照。</p><a href="../../planning/UPS-Fleet-FIN-POD-FSD-v0.1.md">打开 FSD 基线文档 →</a></div>`}
const scenarios=[['normal','正常浏览'],['largeList','60+设备分页'],['empty','零设备'],['loading','加载骨架'],['firstError','首次加载失败'],['offline','浏览器离线'],['partial','局部数据失败'],['sourceDown','告警源不可用'],['outOfRange','超量程观测值'],['newCritical','新严重风险提示'],['cursorExpired','列表游标过期'],['ackUnknown','确认结果未知'],['ackPending','确认完成 / 投影待同步'],['ackConflict','并发确认 / 已由他人确认'],['unsupportedAck','平台不支持确认'],['revisionConflict','发布版本冲突'],['activeBlock','活动规则阻断变更'],['precommitFail','提交前失败'],['postcommitFail','提交后激活失败'],['recovery','配置恢复待处理'],['auditDown','审计不可写'],['sessionExpired','会话过期']];
function showScenarios(){modal('独立原型 · 评审场景',notice('场景开关只设置本地样例状态，无现场采集、设备控制或真实变更。')+`<div class="scenario-grid">${scenarios.map(([v,t])=>btn((state.scenario===v?'● ':'')+t,'scenario:'+v)).join('')}</div>`)}
function applyScenario(v){state.scenario=v;if(v==='largeList'){devices=structuredClone(baseDevices);for(let i=4;i<=60;i++)devices.push({...baseDevices[3],id:'ups-b'+String(i).padStart(2,'0'),name:'UPS-B'+String(i).padStart(2,'0')});location.hash='overview';state.pageNo=1}else if(state.scenario!=='largeList'&&devices.length>10){devices=devices.filter(d=>baseDevices.some(b=>b.id===d.id))}if(v==='cursorExpired'){state.listAt=Date.now()-301000;state.listRevision++;toast('列表已刷新：原游标超过5分钟，按原筛选重新定位设备。');state.scenario='normal'}if(v==='activeBlock'){state.step=4;location.hash='config'}if(v==='outOfRange')location.hash='detail/ups-a01';if(v==='recovery')location.hash='diagnostics';$('#modal').close();render()}
function publishPreview(){if(!state.validated||Date.now()-state.validatedAt>600000){state.validated=false;toast('校验报告已失效，请重新校验');render();return}const reason=$('#publishReason').value.trim();if(!reason){toast('请填写发布理由');return}state.publishReason=reason;modal('发布前差异预览',kv([['基线 / 候选','cfg-'+state.config+' → cfg-'+(state.config+1)],['范围',esc(state.draft.eq)+' · 局部更新；省略对象保持不变'],['字段','映射 '+esc(state.draft.logical)+' / 需求 '+state.draft.q+' min'],['验收影响','关键变更后 ready，撤销旧验收'],['理由',esc(reason)],['告警影响','无活动规则或未决操作才能变更']])+notice('可选空气质量未映射：将保留警告并记录此次发布理由。')+`<div class="actions">${btn('返回修改','close')}${btn('确认发布演示','publish','primary')}</div>`)}
function publish(){if(!canEdit()||['offline','auditDown','recovery'].includes(state.scenario))return;if(state.scenario==='revisionConflict'){state.validated=false;log('配置发布',state.draft.eq,'REVISION_CONFLICT');modal('发布版本冲突',notice('活动配置已变化。原草稿保留，基于最新版本重新合并，必须重新复核和校验；不自动发布。','error')+btn('重新合并草稿','rebase'));return}if(state.scenario==='activeBlock'){modal('变更被阻断',notice('ACTIVE_OCCURRENCE_BLOCKS_CHANGE · occ-101。确认并不解除阻断，需自然恢复或平台管理结束证据。','error'));return}state.pub='PREPARING';modal('发布状态',`<div id="pubState">PREPARING · 准备影子配置</div><p class="muted">离线流程演示 · 所有模块一致后开放闸门。</p>`);const sequence=['PREPARED','QUIESCING','COMMITTED','ACTIVATING','ACTIVE'];let i=0;const t=setInterval(()=>{state.pub=sequence[i++];if(state.scenario==='precommitFail'&&state.pub==='QUIESCING'){clearInterval(t);state.pub='ABORTED';log('配置发布',state.draft.eq,'ABORTED','保持 cfg-'+state.config);$('#pubState').innerHTML=notice('提交前失败：候选作废，旧 cfg-'+state.config+' 继续运行。','error');return}if(state.scenario==='postcommitFail'&&state.pub==='ACTIVATING'){clearInterval(t);state.pub='RECOVERY_REQUIRED';state.scenario='recovery';log('配置发布',state.draft.eq,'RECOVERY_REQUIRED','已提交 cfg-'+(state.config+1)+'；闸门关闭');$('#pubState').innerHTML=notice('提交后激活失败：新决定保留，副作用闸门关闭。不能静默退回旧版本。','error')+btn('查看运行诊断','goDiagnostics');return}if($('#pubState'))$('#pubState').innerHTML=`<h2>${state.pub}</h2><p>${sequence.slice(0,i).join(' → ')}</p>`;if(state.pub==='ACTIVE'){clearInterval(t);state.config++;configArchive[state.config]=structuredClone(state.draft);state.validated=false;const d=devices.find(x=>x.id===state.draft.eq);const priorPlan=configArchive[state.config-1];if(priorPlan&&(priorPlan.due!==state.draft.due||priorPlan.planStatus!==state.draft.planStatus||priorPlan.planTitle!==state.draft.planTitle)){alarms.filter(a=>a.eq===state.draft.eq&&a.kind==='event'&&['upcoming','due'].includes(a.stage)).forEach(a=>a.stage='superseded');const stage=state.draft.planStatus==='completed'?'completed':state.draft.planStatus==='cancelled'?'cancelled':new Date(state.draft.due)<=new Date('2026-09-14')?'due':(new Date(state.draft.due)-new Date('2026-09-14'))/86400000<=Number(state.draft.remind)?'upcoming':null;if(stage)alarms.push({id:'plan-event-'+state.config,eq:state.draft.eq,title:state.draft.planTitle,level:['upcoming','due'].includes(stage)?'warning':'info',activity:'notApplicable',ack:'notRequired',kind:'event',time:'10:00:03',received:'10:00:03',source:'维护计划 · rev'+state.config,stage})}if(d){d.name=state.draft.name;d.status=state.draft.enrollment||'ready';d.risk=null;d.coverage='insufficient';d.q=Number(state.draft.q)}log('配置发布',state.draft.eq,'SUCCEEDED','cfg-'+(state.config-1)+' → cfg-'+state.config);state.operations.push({id:'publish-'+state.config,state:'SUCCEEDED',availability:'ready',action:'配置发布',target:state.draft.eq});$('#pubState').innerHTML=notice('发布演示完成 · cfg-'+state.config+' / epoch-'+state.config+'；设备待验收。','ok')+btn('前往接入验收','goCommission','primary');}},450)}
function checkOperation(id){const a=alarms.find(x=>x.id===id),o=state.operations.find(x=>x.target===id);if(!o)return toast('未找到有权操作');modal('只读核对 · '+o.id,kv([['状态',o.state],['结果可用性',o.availability],['目标',id]])+notice(o.state==='OUTCOME_UNKNOWN'?'执行结果未知；只读对账，不重发确认。30秒后停止自动查询并保留待核对入口。':'确认已完成，结果投影暂缺；只查询状态，不重发。')+btn('演示源证据返回','resolve:'+id,'primary'))}
window.addEventListener('hashchange',()=>{if(state.page==='history'){state.historyFields=['负载率'];state.historyRange='1'}render()});
document.addEventListener('change',e=>{const el=e.target;if(el.id==='role'){state.role=el.value;state.site='';state.alarmEq='';state.scenario='normal';$('#modal').close();render();return}if(el.dataset.draft){state.draft[el.dataset.draft]=el.type==='checkbox'?el.checked:el.value;state.validated=false;return}if(el.dataset.filter){const key=el.dataset.filter;if(key==='draftEq')state.draft.eq=el.value;else if(key==='draftSupport')state.draft.support=el.value;else if(key==='draftPlanStatus')state.draft.planStatus=el.value;else if(key==='draftEnrollment')state.draft.enrollment=el.value;else state[key]=key==='pageSize'?Number(el.value):el.value;if(key.startsWith('draft'))state.validated=false;state.pageNo=1;if(['site','comm','mode','severity'].includes(key)){state.listRevision++;state.listAt=Date.now()}render();return}if(el.dataset.series){let next=el.checked?[...state.historyFields,el.dataset.series]:state.historyFields.filter(x=>x!==el.dataset.series);if(next.length>4){el.checked=false;toast('最多同时4条曲线');return}state.historyFields=next;render()}});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.id==='search'){state.query=e.target.value;state.pageNo=1;state.listRevision++;render()}});
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;const [action,...rest]=el.dataset.action.split(':'),value=rest.join(':');switch(action){
case 'close':$('#modal').close();break;
case 'reset':state.scenario='normal';render();break;
case 'scenario':applyScenario(value);break;
case 'refresh':state.listRevision++;state.listAt=Date.now();toast('列表已刷新 · 固定样例的采集时间保持不变');render();break;
case 'clearFilters':state.query='';state.site='';state.comm='';state.mode='';state.severity='';state.pageNo=1;state.scenario=state.scenario==='empty'?'normal':state.scenario;render();break;
case 'search':state.query=$('#search').value;state.pageNo=1;state.listRevision++;state.listAt=Date.now();render();break;
case 'next':state.pageNo++;render();break;
case 'prev':state.pageNo=Math.max(1,state.pageNo-1);render();break;
case 'unit':state.unit=state.unit==='C'?'F':'C';try{localStorage.setItem('upsPrototypeTemperature',state.unit)}catch{}render();break;
case 'assessment':assessment();break;
case 'metric':state.historyFields=[value];state.historyRange='1';location.hash='history/'+state.eq;break;
case 'metricInfo':modal(value,notice('字段来源、单位和缺失状态已在卡片中说明。仅支持数值且具备历史能力的字段可查询趋势。'));break;
case 'queryHistory':{const from=$('#from').value,to=$('#to').value,days=(new Date(to)-new Date(from))/86400000;if(state.historyRange==='custom'&&(!from||!to||days<=0||days>7)){toast('起止时间必填，结束须晚于起始，范围不超过7天');return}if(!state.historyFields.length){toast('请至少选择1条曲线');return}state.historyFrom=from;state.historyTo=to;state.historyLabel=state.historyRange==='custom'?from+' 至 '+to:'最近 '+state.historyRange+' 小时（示意曲线）';toast('已更新查询条件 · 固定趋势夹具');render();break}
case 'retryHistory':state.historyStatus='normal';render();break;
case 'deviceEvents':state.alarmEq=state.eq;state.alarmView='all';location.hash='alarms';break;
case 'alarmView':state.alarmView=value;render();break;
case 'alarm':alarmDetail(value);break;
case 'ack':ackDialog(value);break;
case 'submitAck':{const comment=$('#ackComment').value.trim();if(!comment||comment.length>500){$('#ackError').textContent='请填写1–500字符的备注。';return}if(!canAck())return;const a=visibleAlarms().find(x=>x.id===value);if(!a||a.ack!=='unacknowledged'||a.pending)return;let outcome='SUCCEEDED',availability='ready';if(state.scenario==='ackUnknown'){outcome='OUTCOME_UNKNOWN';a.pending=true}else if(state.scenario==='ackPending'){availability='pending';a.pending=true}else if(state.scenario==='ackConflict'){outcome='ALREADY_APPLIED';a.ack='acknowledged';a.actor='李工';a.ackTime='10:00:01';a.comment='源系统已先确认'}if(outcome==='SUCCEEDED'){a.ack='acknowledged';a.actor='陈工';a.ackTime='10:00:02';a.comment=comment}const id=log('告警确认',value,outcome,'activity 保持 '+a.activity);state.operations.push({id,state:outcome,availability,action:'告警确认',target:value});$('#modal').close();render();if(a.pending)checkOperation(value);else toast(outcome==='ALREADY_APPLIED'?'已由李工确认，保留原确认人和备注。':'确认演示完成；活动状态未改变。');break}
case 'operation':checkOperation(value);break;
case 'resolve':{const o=state.operations.find(x=>x.target===value),a=alarms.find(x=>x.id===value);if(!o||!a)return;o.state='SUCCEEDED';o.availability='ready';a.pending=false;a.ack='acknowledged';a.actor=a.actor||'陈工';a.ackTime='10:00:02';a.comment=a.comment||'源回读证据确认';log('告警确认',value,'SUCCEEDED','源证据核对完成；无第二次确认');$('#modal').close();render();toast('源结果已核实，审计补记完成（演示）');break}
case 'step':state.step=Number(value);render();break;
case 'saveDraft':try{localStorage.setItem('upsPrototypeDraft',JSON.stringify(state.draft));toast('草稿已保存在当前浏览器，可继续编辑')}catch{toast('浏览器不允许本地保存，草稿仍保留在本页')}break;
case 'pointPreview':modal('只读点预览',notice('固定夹具，不是 FIN 读取结果。')+kv([['点 Ref',esc(state.draft.point)],['原值 / 单位','76 / '+esc(state.draft.rawUnit)],['归一值',76*Number(state.draft.scale)+Number(state.draft.offset)+' '+esc(state.draft.unit)],['质量','good'],['源时间',stamp],['映射版本','draft-local'],['rawKind / origin','Number / measured']]));break;
case 'validate':validation();break;
case 'publishPreview':publishPreview();break;
case 'publish':publish();break;
case 'rebase':state.config++;state.validated=false;state.scenario='normal';state.step=4;$('#modal').close();render();toast('原 patch 已重新合并到最新基线，请复核并重新校验。');break;
case 'versions':modal('配置版本历史',`<div class="rulebox"><h3>cfg-${state.config} · 当前版本</h3><p>作用范围：当前授权设备</p></div><div class="rulebox"><h3>cfg-${Math.max(1,state.config-1)} · 历史版本</h3><p>回退只生成有权范围草稿，保留历史解释与审计。</p>${btn('生成回退草稿','rollback:'+Math.max(1,state.config-1))}</div>`);break;
case 'rollback':if(configArchive[Number(value)])state.draft=structuredClone(configArchive[Number(value)]);state.validated=false;state.step=0;log('回退草稿',state.draft.eq,'PREPARED','来源 cfg-'+value+'；未发布');state.scenario='normal';$('#modal').close();location.hash='config';render();toast('已建立授权范围恢复草稿；需复核、校验并发布新版本。');break;
case 'goDiagnostics':$('#modal').close();location.hash='diagnostics';break;
case 'goCommission':$('#modal').close();location.hash='commission';break;
case 'accept':{const checked=[...document.querySelectorAll('.acceptCheck')].every(x=>x.checked),ev=$('#acceptEvidence').value.trim(),rev=$('#acceptRevision').value;if(!checked||!ev||rev!=='cfg-'+state.config){$('#acceptError').textContent='必须完成全部证据项、填写证据引用，且报告版本与当前配置一致。';return}const d=devices.find(x=>x.id===state.draft.eq);if(d){d.status='accepted';d.coverage='insufficient';d.risk=null}state.config++;configArchive[state.config]=structuredClone(state.draft);log('接入验收',state.draft.eq,'SUCCEEDED','ready → accepted / acceptance-local；样例数据未变化');toast('验收流程演示通过；固定样例缺失数据仍保留不可评估。');render();break}
case 'queryAudit':{const days=(new Date($('#auditTo').value)-new Date($('#auditFrom').value))/86400000;if(!Number.isFinite(days)||days<0||days>31){$('#auditError').textContent='查询窗口须有效且不超过31天';return}$('#auditError').textContent='';$('#auditRows').innerHTML=auditRows($('#auditAction').value,$('#auditFrom').value,$('#auditTo').value);break}
}});
$('#scenarioOpen').addEventListener('click',()=>showTools());

